/* English text for the glossary: group introductions, definitions and notes, keyed to the Chinese data in glossary-data.ts. */
export const GROUP_INTRO_EN: string[] = [
  'Start with how data is represented, then ask how a model learns, how it is compared and what the evidence can support.',
  'First tell apart the research field, the learning method and the type of task.',
  'When reading a method chapter, first find the inputs, the labels, the training method and the validation data.',
  'The model makes predictions; explanation methods help analyse how a prediction was formed.',
  'From tokens and context to fine-tuning, retrieval and generation.',
  'Five routes from cheapest to heaviest: a prompt for quick tries, RAG when facts must be looked up, embedding plus classifier for fixed categories, fine-tuning for a steady style, and LoRA as a lighter way to fine-tune.',
  'From simple LLM pipelines to compound AI systems to autonomous agents, and how to build and evaluate them.',
  'Keep the research object, the scope of the explanation and the names of the methods apart.',
  'Whether a prediction is right, whether an explanation is accurate and whether users understand it are related but different evaluation questions.',
  'After launch, the data, the model and the context of use keep changing.',
  'These words are used differently across disciplines; below they are explained in the research context of this guide.',
  'AI systems can produce unfair outcomes, leak information from their training data, or be talked into bypassing safety limits. These entries explain what each problem is, how it happens, and how researchers test for and reduce it.',
  'AI uses energy and water, and is shaped by laws, guidance and licence terms. These entries are introductory only; check the official texts for the exact rules.',
];

export const TERM_EN: Record<string, { def: string; note?: string; mechanism?: string; goodFor?: string }> = {
  mlp: { def: 'Multilayer perceptron: every unit is connected to every unit in the next layer.', mechanism: 'Multilayer perceptron: every unit is connected to every unit in the next layer.', goodFor: 'tabular data, small sets of sensor features.', note: 'Our example: six sensor features enter two fully connected layers, which output a normal / faulty classification.' },
  cnn: { def: 'Small filters slide over the input and detect local patterns such as edges and textures.', mechanism: 'Small filters slide over the input and detect local patterns such as edges and textures.', goodFor: 'images, video, spectrograms.', note: 'Our example: a cat-face image is first scanned for ear edges and textures, then combined patterns support pose classification.' },
  'rnn-lstm': { def: 'Reads a sequence one step at a time and carries a memory forward.', mechanism: 'Reads a sequence one step at a time and carries a memory forward.', goodFor: 'time series, sensor streams; older speech and text models.', note: 'Our example: reading a vibration stream second by second carries the earlier motion into the current estimate of whether a device is becoming abnormal.' },
  transformer: { def: 'Every element looks at every other one through attention.', mechanism: 'Every element looks at every other one through attention.', goodFor: 'text, images, audio; almost all foundation models.', note: 'Our example: in a sentence, the current token can directly use the positions of other tokens when updating its representation.' },
  scalar: { def: 'A quantity with one numerical value, such as a temperature or one loss value; it contrasts with a vector, matrix or tensor that contains multiple values.', note: 'Our example: treating “this grasp took 2.4 seconds” as one scalar cannot express the whole motion trajectory.', mechanism: 'A single number.', goodFor: 'One temperature reading.' },
  vector: { def: 'An ordered list of numerical values that can represent a sample’s features, a direction or one learned representation.', note: 'Our example: a vector of ear angle, eye aperture and movement amplitude lets a model process the three cues together.', mechanism: 'An ordered list of numbers.', goodFor: 'Six sensor readings from one record; a word turned into numbers.' },
  matrix: { def: 'A rectangular arrangement of numbers in rows and columns; it can hold batches of samples or transform one vector into another.', note: 'Our example: arranging 100 samples with six features as a 100×6 matrix lets a linear model process the batch together.', mechanism: 'Numbers in rows and columns.', goodFor: 'A data table, one sample per row.' },
  tensor: { def: 'A numerical array with potentially multiple axes, generalising scalars, vectors and matrices; deep learning often uses tensors to carry batches and features.', note: 'Our example: a batch of colour images can be represented as a batch × height × width × colour-channel tensor.', mechanism: 'An array with any number of axes: one is a vector, two is a matrix.', goodFor: 'A batch of colour photos: count, height, width, colour.' },
  dimension: { def: 'A concept describing the number of independent coordinates or features in a representation; in other contexts it can mean the number of axes in an array, so the meaning should be stated.', note: 'Our example: a vector with 300 features has 300 coordinates; compressing it to 20 dimensions changes what information is retained.', mechanism: 'How many coordinates the data needs, or how many axes an array has.', goodFor: '“6 features” means 6 dimensions.' },
  representation: { def: 'The form data takes at a model’s input or inside the model; a representation determines which relationships the model can see and affects prediction and explanation.', note: 'Our example: representing a video as raw pixels exposes different cues from representing it as movement speed and posture changes.', mechanism: 'Rewrites raw data into a form the model can read; how you write it decides what the model can see.', goodFor: 'A vibration signal as a spectrum; a word as a vector.' },
  'probability-distribution': { def: 'A rule describing possible outcomes and their probabilities; probabilities sum to one for discrete outcomes, while continuous outcomes are described through densities and interval probabilities.', note: 'Our example: a model can output a distribution—fear 0.6, alert 0.3 and calm 0.1—instead of only “fear”.', mechanism: 'Lists each outcome with its probability; they add up to 1.', goodFor: 'A die: 1 to 6, each 1/6.' },
  likelihood: { def: 'With observed data held fixed, a measure of how well different parameter values support those data; likelihood is not the probability of a parameter itself.', note: 'Our example: after observing coin flips, likelihood compares which values of the heads probability best explain that set of results.', mechanism: 'Holds the data fixed and asks which parameters make it look most reasonable.', goodFor: '7 heads in 10 flips: is the coin biased?' },
  entropy: { def: 'A measure of the uncertainty in a probability distribution; a more even distribution usually has higher entropy, while a concentrated one has lower entropy.', note: 'Our example: five class probabilities near 0.2 are more uncertain than a distribution that puts almost all mass on one class.', mechanism: 'The more even the outcomes, the harder to guess, and the higher the entropy.', goodFor: 'A fair coin is high; a coin that almost always lands heads is low.' },
  expectation: { def: 'A probability-weighted average of possible outcomes; it summarises a distribution and does not have to be an outcome observed in one trial.', note: 'Our example: weighting the costs of repair options by their probabilities estimates the expected cost.', mechanism: 'Multiplies each outcome by its probability and adds them up.', goodFor: 'A die averages 3.5, though it never rolls 3.5.' },
  correlation: { def: 'A statistical association describing how two variables vary together; correlation by itself does not show that one variable causes the other.', note: 'Our example: ice-cream sales and drowning incidents both rise in summer; temperature may affect both, so sales need not cause drowning.', mechanism: 'Two quantities rise and fall together.', goodFor: 'On hot days, more ice cream is sold.' },
  causation: { def: 'A relationship in which intervening on one variable changes an outcome; causal claims have direction and an intervention meaning.', note: 'Our example: only when increasing camera exposure changes error rates in an otherwise controlled experiment is a causal effect plausible.', mechanism: 'Change A on purpose and B changes with it.', goodFor: 'You changed a button’s colour and clicks really went up.' },
  'causal-inference': { def: 'The use of experiments or observational data plus explicit assumptions to estimate the causal effect of an intervention, treatment or exposure on an outcome.', note: 'Our example: when comparing whether a prompt improves task completion, state how participants were randomised or how confounders were adjusted.', mechanism: 'Uses experiments, or data with explicit assumptions, to estimate what a change does.', goodFor: 'Did a new course really raise grades?' },
  confounder: { def: 'A variable that affects both the treatment or exposure and the outcome, potentially creating or hiding an apparent association; identifying confounders is central to causal analysis.', note: 'Our example: user experience may affect both whether assistance is enabled and task completion, making the feature look more effective than it is.', mechanism: 'A third factor that drives both A and B.', goodFor: 'Hot weather lifts ice cream sales and swimmers together.' },
  normalization: { def: 'A transformation that puts values onto a more comparable range or scale, making features with different units easier to use together.', note: 'Our example: mapping pixel values from 0–255 to 0–1 prevents their numerical range from overwhelming other inputs.', mechanism: 'Squeezes values into one range, such as 0 to 1.', goodFor: 'Temperature (tens) and pressure (tens of thousands) in one model.' },
  standardization: { def: 'A common transformation that centres a feature with the training-set mean and scales it by the training-set standard deviation, giving values with approximately zero mean and unit scale.', note: 'Our example: use only training-set statistics; including test-set means leaks evaluation information.', mechanism: 'Subtracts the training mean, then divides by the training standard deviation.', goodFor: 'Turning height and weight into “how far above or below average”.' },
  'feature-engineering': { def: 'Constructing, selecting or transforming features from raw data using task knowledge; it changes the representation available to the model.', note: 'Our example: deriving “weekend” and “hours since the last event” from a timestamp can be more useful than passing the date directly.', mechanism: 'Uses task experience to build inputs that help the model more.', goodFor: 'Peak and main frequency from a vibration trace.' },
  'dimensionality-reduction': { def: 'Representing high-dimensional data with fewer coordinates while trying to retain structure or information relevant to the task; reduction can also discard task-relevant detail.', note: 'Our example: compressing 200 sensor features to two dimensions helps plotting, but closeness on the plot does not guarantee similar predictions.', mechanism: 'Describes the data with fewer coordinates.', goodFor: 'Squeezing dozens of features into 2D to plot the groups.' },
  'objective-function': { def: 'The quantity an optimisation procedure tries to minimise or maximise, making explicit what counts as better; a loss function is often an objective to minimise.', note: 'Our example: combining error and model complexity in the objective says “accurate and not unnecessarily complex” is better than accuracy alone.', mechanism: 'One number that defines what counts as good.', goodFor: 'The smaller the prediction error, the better.' },
  optimization: { def: 'Searching a parameter or decision space for values that improve an objective; lowering training loss does not by itself prove better performance in the real setting.', note: 'Our example: after gradient descent lowers training loss, unseen data still need to be checked for memorisation.', mechanism: 'Keeps adjusting parameters so the objective gets better.', goodFor: 'Lowering the error step by step during training.' },
  'bias-variance': { def: 'Bias is systematic error from assumptions that are too restrictive, while variance is sensitivity to changes in the training sample; model complexity often involves a trade-off between them.', note: 'Our example: a rigid line may underfit, while a highly flexible curve may follow sample fluctuations; validation data help compare the trade-off.', mechanism: 'Too simple and it errs in a systematic way; too sensitive and a new batch changes everything.', goodFor: 'A straight line forced through curved data; a curve chasing every dot.' },
  'out-of-distribution': { def: 'An input whose important distribution differs from the training data; a model can be highly confident on such an input without actually knowing that setting.', note: 'Our example: a camera model trained indoors may see night-time outdoor footage as out of distribution, so its original accuracy cannot be assumed.', mechanism: 'Input very different from what training saw.', goodFor: 'A model trained on sunny photos meets heavy snow.' },
  benchmark: { def: 'A comparison setup with fixed tasks, data, metrics and a protocol; it helps compare methods but does not prove reliability in every deployment context.', note: 'Our example: two models’ scores on one public test set are comparable, but that does not guarantee equal performance for new users or devices.', mechanism: 'The same tasks and metrics, so methods compare fairly.', goodFor: 'Several models scored on one test set.' },
  reproducibility: { def: 'The extent to which others can obtain the same or comparable result from the reported materials, code, data processing and procedure.', note: 'Our example: reporting only the best score without the random seed, data split and preprocessing makes the comparison hard to reproduce.', mechanism: 'Others using your data and steps get similar results.', goodFor: 'A paper ships code and data so readers can redraw the figure.' },
  'multimodal-representation': { def: 'A representation that places or links different modalities—such as text, images, sound or action—so a model can use relationships across them.', note: 'Our example: encoding a cat posture image and the phrase “ears back” into comparable representations lets a model learn their correspondence.', mechanism: 'Puts text, images and sound into one space so they match up.', goodFor: 'Type “sunset at the beach” and find matching photos.' },
  ai: { def: 'A broad field in which computing systems carry out tasks such as perception, language, reasoning or decision-making. Machine learning is one branch of it.' },
  ml: { def: 'Methods that learn regularities from data so that a model can predict or generate outputs.' },
  'deep-learning': { def: 'A family of machine-learning methods that use multi-layer neural networks to learn representations of data and the relationship between inputs and outputs.' },
  'generative-ai': { def: 'Models and systems that learn patterns in data and generate text, images, sound and other content.' },
  supervised: { def: 'Learns the relationship from input to target output from samples that come with target labels.', note: 'Our example: learning failure prediction from sensor data recording “grasp succeeded / failed”.' },
  unsupervised: { def: 'Looks for structure or patterns in data for which no target labels are specified.', note: 'Our example: grouping equipment operation records into a few groups by vibration pattern, then having an engineer interpret each group.' },
  'self-supervised': { def: 'Builds the training target from the data itself, for example predicting a hidden word or the next token from a piece of text.', note: 'Even without labelling each item by hand, there can still be a clear training objective.' },
  'reinforcement-learning': { def: 'An agent interacts with an environment and learns a policy of action from reward signals, in order to increase cumulative return.' },
  policy: { def: 'In reinforcement learning, the rule or probability distribution that decides which action to take in a given state.' },
  classification: { def: 'Predicts which class a sample belongs to, or gives prediction scores for each class.', note: 'Our example: “normal / faulty” is classification; “how many hours it can still run” is regression.', mechanism: 'The model reads the input and picks one label from a fixed set.', goodFor: 'spam, sentiment, ticket sorting.' },
  regression: { def: 'The task of predicting a numerical value, such as temperature, load or expected service life.' },
  clustering: { def: 'Organises samples into groups by similarity; the groups are usually not labels specified before training.' },
  'transfer-learning': { def: 'Uses a representation learned on one task or dataset for another task, reducing the need to learn from scratch.' },
  'foundation-model': { def: 'A model trained on broad data that can be adapted to many downstream tasks.', note: '“Foundation model” stresses an adaptable role; “large language model” stresses language modelling. The two are not exactly the same category.' },
  dataset: { def: 'A set of data samples organised for training, evaluation or analysis.' },
  sample: { def: 'One instance a model processes, for example one grasp record or one image.' },
  feature: { def: 'An attribute or representation in the input that the model uses, for example temperature, speed, or a representation learned from an image.' },
  label: { def: 'A recorded value used as the target during learning or evaluation, for example a species class or a measured energy use.' },
  'ground-truth': { def: 'An observation or annotation used as the basis for the answer in evaluation. Its reliability depends on measurement, annotation and how the task is defined.' },
  model: { def: 'The computational structure and parameters that map inputs to outputs; after training it can make predictions for new samples.' },
  training: { def: 'The process of adjusting a model with training data and a target so that it does the task better.' },
  inference: { def: 'Running a model on an input to produce a prediction or generated result. It usually does not mean the model’s parameters are being updated.', note: 'In engineering documents “inference” often means running the model; “reasoning” usually refers to the ability to solve problems step by step.' },
  prediction: { def: 'The output a model gives for an input; it can be a class, a number or a probability distribution.' },
  parameter: { def: 'Numerical values in a model that are learned or adjusted during training; the weights of a neural network are a common example.' },
  hyperparameter: { def: 'Settings that control the model or the training process, such as the learning rate or the maximum depth of a tree.', note: 'Features are inputs; parameters are values the model learns; hyperparameters are the settings of training and model design.' },
  loss: { def: 'A function that turns the difference between predictions and the training target into an optimisation signal.' },
  'gradient-descent': { def: 'An optimisation method that repeatedly makes small updates to parameters in the direction that lowers the loss, based on how the loss changes with each parameter.' },
  'learning-rate': { def: 'A training setting that controls the step size of each parameter update.' },
  'batch-epoch': { def: 'A batch is the group of samples processed at one time; an epoch is one full pass through the training set.' },
  'dataset-split': { def: 'The training set is used to learn; the validation set to choose options and tune settings; the test set for the final assessment on unseen data.', note: 'Whether similar records from the same person, or neighbouring time slices, may cross between sets depends on the research goal; decide it carefully to avoid accidental leakage.' },
  overfitting: { def: 'The model fits the training data too closely and therefore performs worse on new data.' },
  underfitting: { def: 'The model has not learned the relationships in the task well, so it performs poorly even on the training data.' },
  generalization: { def: 'The ability of a model to apply what it has learned to unseen samples.' },
  regularization: { def: 'A family of methods that constrain the complexity of a model or of training to help reduce overfitting.' },
  'data-leakage': { def: 'Training or model selection used information that should not be available at prediction time, so the evaluation looks too good.', note: 'Our example: predicting “whether it failed before repair” using “the parts replaced during repair” would give away the answer in advance.' },
  'decision-tree': { def: 'A model that splits the input space through a sequence of feature conditions and gives a prediction at each leaf node.' },
  'random-forest': { def: 'Combines many randomised decision trees: classification results are voted on, and numerical predictions are averaged.' },
  ensemble: { def: 'Ways of combining several models into one prediction system. Random forests and gradient boosting are different ensemble routes.' },
  boosting: { def: 'A family of methods that add models one after another, so that each later model improves the overall prediction so far; trees are often the base model.' },
  xgboost: { def: 'An efficient learning system for gradient boosting, often used for prediction on tabular data. It is a modelling tool, not an XAI explainer.' },
  'neural-network': { def: 'A model made of interconnected computing layers that learns the relationship between inputs and outputs through parameters and non-linear transformations.' },
  activation: { def: 'A function applied to the output of a computing unit; non-linear activations help a network express complex relationships.' },
  backpropagation: { def: 'Computes the gradients of the loss with respect to each parameter by working backwards through the computation; usually used with gradient descent to train networks.' },
  embedding: { def: 'Represents objects as numerical vectors, so that relationships relevant to a task can be expressed in the vector space.', note: 'Our example: once material descriptions become vectors, they can be retrieved by similarity of representation, not only by matching the original words.', mechanism: 'Turn a word, image or sentence into a list of numbers so similar things sit close together.', goodFor: 'search, recommendation, similarity.' },
  'surrogate-model': { def: 'A model used to approximate another complex model or an expensive process. LIME uses a local explanation surrogate; the engineering case uses a surrogate to approximate simulation.', note: 'Both are called “surrogate”, but their purposes and the errors they need to be checked for are different.' },
  llm: { def: 'A model trained on large amounts of language data that learns statistical relationships between token sequences, and can be used to generate, understand and transform language.' },
  token: { def: 'A discrete unit processed by a language model; it can be a word, a sub-word or a character, and does not always correspond one-to-one to a Chinese character or an English word.' },
  tokenizer: { def: 'The component that turns text into tokens and their numbers, and can turn a sequence of numbers back into text.' },
  context: { def: 'Context is the input information the current prediction can use; the context window is the range that can be processed at one time, usually counted in tokens.', note: 'Chat history, retrieved material and instructions can all take up context; the exact range depends on the model and the system settings.' },
  /* Transformer is defined with the model-family mechanism and use-case line above. */
  attention: { def: 'Computes how much each position’s representation contributes to the current one and integrates information by those weights; self-attention operates within one sequence.', note: 'Here “attention” is a computational mechanism; using it to explain the basis of a model that users care about needs separate justification.' },
  'encoder-decoder': { def: 'An encoder turns the input into representations; a decoder uses those representations and the outputs so far to generate a sequence. Transformer models can use different combinations of these structures.' },
  pretraining: { def: 'Training a model first on broad data, so that it gains abilities and representations that later tasks can use.', mechanism: 'Let the model read huge amounts of data and learn general knowledge by repeatedly predicting what comes next.', goodFor: 'building a general base before adapting.' },
  'fine-tuning': { def: 'Continues training the parameters of a pretrained model so that it fits a specific task, domain or behaviour requirement better.', mechanism: 'Keep training an existing model on your examples so its weights shift toward your task.', goodFor: 'a fixed style or special output format.' },
  prompt: { def: 'A prompt is the task input given to a model; prompt engineering is the practice of organising instructions, context and examples to guide the output.', note: 'Changing the prompt usually happens at use time; fine-tuning involves training parameters.', mechanism: 'Describe the task and requirements in words, and the model answers accordingly.', goodFor: 'quick tries without changing the model.' },
  'few-shot': { def: 'Gives a few demonstrations in the prompt so that the model handles a new task in the same way. Zero-shot gives no such task demonstrations.', mechanism: 'Put a few worked examples in the prompt and the model follows the pattern.', goodFor: 'formats or tones hard to describe in words.' },
  distillation: { def: 'Uses the outputs or other information of a larger or stronger model to train another model, often to obtain a smaller and more efficient one.' },
  sft: { def: 'Continues training a model on input–output examples of the task, for example on instructions and high-quality answers so that it learns to follow instructions.' },
  rlhf: { def: 'A training pipeline that uses human preferences or feedback to form a reward signal, then uses reinforcement learning to adjust the model’s behaviour.', note: 'Human preference gives one optimisation signal; it does not automatically guarantee that every answer is accurate.' },
  lora: { def: 'A parameter-efficient adaptation method that freezes the original model weights and trains a small set of low-rank update matrices.', mechanism: 'Freeze the original weights and train two small side matrices that represent the change.', goodFor: 'cheap customization of big models.' },
  rag: { def: 'A system approach that first retrieves external material related to the question, then uses that material to generate the answer.', note: 'Our example: first look up the product repair manual, then answer based on the retrieved passages. Check both retrieval quality and whether the answer stays faithful to the material.', mechanism: 'Look up relevant passages in a document store, then give them to the model along with the question.', goodFor: 'answers based on fresh or private documents.' },
  decoding: { def: 'Rules that turn the token probabilities a model gives into the actual output sequence; one can pick the highest-scoring item or sample.' },
  temperature: { def: 'A parameter that adjusts how sharp the probability distribution is during generation. Lower values usually concentrate sampling on high-probability candidates.', note: 'It controls sampling behaviour; it is not a switch for answer accuracy.' },
  'top-p': { def: 'A strategy that samples the next token from the smallest set of candidates whose cumulative probability reaches a set threshold.' },
  hallucination: { def: 'Generated content that does not agree with its basis, the input, or checkable facts. The exact judgement depends on the task and the definition used.' },
  'chain-of-thought': { def: 'A prompting or generation approach that works through a problem with intermediate written steps.', note: 'Intermediate text helps show the solution steps; whether it reflects the model’s real basis for the answer is a separate research question.' },
  reasoning: { def: 'In discussions of LLMs, usually the ability and process of organising information over several steps, reaching a conclusion, or solving a complex problem.' },
  xai: { def: 'Methods, systems and interactions that research and design ways for people to understand an AI’s behaviour and its basis.' },
  interpretability: { def: 'Papers do not always use these two words in the same way: one often stresses how far a model can be understood, the other the ability to give explanations. Follow the author’s definition when reading.', mechanism: 'Inspect and analyze a model\'s inner numbers to work out why it gave a result.', goodFor: 'Wanting to know why a model decided as it did.' },
  explanation: { def: 'Selects and organises information about a system’s behaviour in response to a question from a particular recipient.' },
  'intrinsic-posthoc': { def: 'Intrinsic interpretability relies on a model’s own checkable structure; post-hoc explanation analyses an already-trained model or its outputs.' },
  'local-global': { def: 'Local explanation focuses on one case; global explanation looks at the regularities of the model’s behaviour across a wider range.' },
  'agnostic-specific': { def: 'Model-agnostic methods do not depend on any one model’s internal structure; model-specific methods use information particular to the model, such as tree structure or gradients.' },
  attribution: { def: 'An analysis that assigns the change in an output, relative to a reference, or its related influence, to input features. Different methods assign with different meanings.' },
  baseline: { def: 'The starting point used for comparison in an explanation. In SHAP the baseline depends on the reference setting; in experiments “baseline” can also mean a comparison model or condition.' },
  shap: { def: 'An additive attribution framework based on Shapley ideas that assigns the difference between a prediction and a reference to the features.' },
  treeshap: { def: 'A method that uses tree structure to compute SHAP attributions efficiently.' },
  treeinterpreter: { def: 'For supported scikit-learn tree models, decomposes a prediction along the decision path: baseline plus each feature’s contribution equals the prediction.', note: 'It accumulates the node-prediction changes along the path; TreeSHAP uses a different attribution principle.' },
  lime: { def: 'Perturbs the input near a target sample and approximates the original model’s local behaviour with a simple surrogate model.' },
  'grad-cam': { def: 'Combines the class gradients with convolutional feature maps to produce a coarse map of the regions relevant to the target class.' },
  saliency: { def: 'A visual representation showing, on spatial or input positions, scores for how sensitive or contributory the model is to a particular output.' },
  counterfactual: { def: 'Gives a changed input under which the model would reach a different or desired result.' },
  dice: { def: 'A method that generates several counterfactual options that differ from each other while staying close to the current case.' },
  actionability: { def: 'Whether a change in an explanation or suggestion can actually be carried out by the relevant person under real constraints.', note: 'Our example: “moving the sensor to another position” may be actionable; “changing history that has already happened” usually is not.' },
  tcav: { def: 'Uses examples of a concept to define a direction, then tests how sensitive the model is to that direction for a concept people can understand.' },
  'concept-bottleneck': { def: 'First predicts interpretable concepts, then predicts the result from those concepts, forming an intermediate layer that can be checked or intervened on.' },
  intervention: { def: 'Deliberately changing a model’s input, concepts or internal variables, and observing how the later results change.' },
  pdp: { def: 'For a chosen feature across different values, averages over the sample distribution of the other features, to show the model’s average prediction change.' },
  ice: { def: 'For a single sample, changes one feature while keeping the other inputs fixed, and observes the prediction curve.' },
  'permutation-importance': { def: 'After shuffling a feature, observes how much the model’s score drops, to measure how much the model depends on it for the given data.', note: 'Strongly correlated features can stand in for each other; keep this in mind when reading importances.' },
  mechanistic: { def: 'Studies which internal representations and computational processes together form the output; often combines structural analysis with interventions to test hypotheses.', mechanism: 'Trace specific units and connections layer by layer to reconstruct the steps it computes.', goodFor: 'Seeing how a model actually computes an answer.' },
  accuracy: { def: 'The number of correctly classified samples divided by all samples.', note: 'Our example: 90 correct judgements out of 100 gives 90% accuracy; with imbalanced classes, other measures are also needed.' },
  precision: { def: 'Among the samples the model labels positive, the proportion that really are positive: TP / (TP + FP).' },
  recall: { def: 'Among the real positives, the proportion the model correctly finds: TP / (TP + FN).' },
  f1: { def: 'The harmonic mean of precision and recall, used to observe both together: 2PR / (P + R).' },
  'confusion-matrix': { def: 'Counts arranged by true class and predicted class, showing correct classifications and where errors went.' },
  'false-positive': { def: 'A false positive is a true negative judged positive; a false negative is a true positive judged negative. What the positive class means must be defined from the task first.', note: 'Our example: judging a normal device as faulty is a false positive; missing a real fault is a false negative.' },
  'roc-auc': { def: 'Summarises the relationship between the true-positive rate and the false-positive rate across thresholds, measuring how well a binary model separates positives from negatives.' },
  rmse: { def: 'Square the prediction errors, average them, then take the square root; the result has the same unit as the target and is more sensitive to large errors.' },
  'r-squared': { def: 'A score for how well a regression fits, relative to a baseline that predicts the mean of the observed targets; it can be negative on a test set.', note: 'In the vehicle side-impact case, R² evaluates the surrogate model’s predictions, not the quality of the explanation directly.' },
  'cross-validation': { def: 'Estimates model performance with several train/validation splits; the way the data are split should match independence, grouping or time order.' },
  calibration: { def: 'How closely predicted probabilities match how often the events actually occur.', note: 'Intuition: if many events given an 80% probability really occur about 80% of the time, the probabilities are well calibrated.' },
  uncertainty: { def: 'Describes how unsure the model is about its result or about its own knowledge; it can be split into uncertainty associated with noise in the data and uncertainty associated with the model’s knowledge.' },
  'aleatoric-epistemic': { def: 'The former comes from data factors such as observation noise; the latter relates to a lack of model knowledge and can usually be reduced by adding relevant data.' },
  faithfulness: { def: 'How closely an explanation corresponds to the model behaviour or basis it describes. The specific test depends on what is explained and by which method.' },
  stability: { def: 'Whether an explanation changes disproportionately for similar inputs or comparable conditions. Research needs to state how the comparison is made.' },
  robustness: { def: 'Whether a model or an explanation keeps the required properties under perturbations, noise or changes in conditions.' },
  'sanity-check': { def: 'Checks with a discriminating control to see whether a method really responds to the information it should depend on, for example by randomising the model’s parameters and then looking at the saliency map.' },
  'kendall-tau': { def: 'Measures the association between two rankings by comparing whether pairs of samples are ordered consistently or inconsistently.' },
  rbo: { def: 'Compares how much two ranked lists overlap; it can weight the top of the list more and handles lists that are not identical or are incomplete.' },
  ablation: { def: 'Removes or changes one component and compares the results, to study that component’s role in the system.' },
  mlops: { def: 'Engineering practices that connect developing a model with running it continuously: data, training, testing, deployment, monitoring and updating.', note: 'For designers, the key is to know who notices a failure, who can update, and which behaviours need to be explained again after an update. This sentence is an application note.' },
  pipeline: { def: 'Connects the steps of data processing, training, validation and deployment into a process that can be run repeatedly.' },
  'ci-cd-ct': { def: 'CI automatically checks integrated changes; CD supports delivering validated versions; CT triggers retraining when needed.' },
  deployment: { def: 'Putting a model into a runtime environment that applications can call, so that it can actually handle requests.' },
  monitoring: { def: 'Continuously observes data, model performance, runtime status and real-use indicators to spot changes and problems.' },
  'data-drift': { def: 'The distribution of current input data has changed relative to reference data. The change is a signal to check; it does not necessarily mean the task performance has dropped.', note: 'Our example: after switching packaging material, the colour and reflection distribution in the robot camera input changes.' },
  'training-serving-skew': { def: 'The data, features or processing in the training stage do not match those in the stage where the model serves real requests.' },
  'experiment-tracking': { def: 'Records the parameters, metrics and artefacts of a training run or evaluation, so that runs can be compared, traced and reproduced.' },
  'model-registry': { def: 'A catalogue or service that manages model versions, metadata and lifecycle information in one place.' },
  'model-card': { def: 'A structured document recording a model’s intended use, evaluation conditions, performance and limitations.' },
  datasheet: { def: 'A document recording a dataset’s motivation, composition, collection process, intended uses and maintenance.' },
  latency: { def: 'The time from sending a request to receiving the response. The measured scope should be stated, such as model computation or the whole interaction.', note: 'Our example: a voice prompt that sounds two seconds late may miss the timing of a collaborative action.' },
  'human-ai': { def: 'HCI studies the interaction of people with computing systems; “Human–AI interaction” focuses more on systems with AI capabilities that predict or generate.' },
  'mental-model': { def: 'The user’s internal understanding of how a system works; it shapes expectations, interpretations and actions.' },
  'explanation-needs': { def: 'The questions a person needs an explanation to answer during a task, for example why this was chosen, why not the other, and how to change the outcome.' },
  contrastive: { def: 'Explains by answering “why this, and not that”; the alternative outcome users expected is an important clue for understanding.' },
  trust: { def: 'The user’s attitude towards a system’s capability, behaviour or reliability. It relates to actual acceptance, but it is not the same thing being measured.' },
  'appropriate-reliance': { def: 'Choosing well to accept, reject or check a system’s output, given its capabilities and limits in the current situation.' },
  understanding: { def: 'Whether the user forms enough of an understanding to support the current task. It can be studied through restating it, predicting new cases and actual performance.' },
  agency: { def: 'The ability and room a person has, in an interaction, to form intentions, make choices and affect outcomes. Here the focus is on actions such as correcting, rejecting and controlling.' },
  'human-in-loop': { def: 'Involves people in key parts of a system, for example labelling, reviewing, correcting, or deciding whether to carry out an action. The points where people take part must be stated.' },
  legibility: { def: 'How easily an agent’s goal can be inferred from the actions already observed.' },
  predictability: { def: 'Whether a system’s later behaviour matches an observer’s expectations, when the goal or situation is known.' },
  'embodied-cues': { def: 'Cues that convey state or intention through perceivable behaviour such as gaze, posture, gestures and movement.' },
  workload: { def: 'The burden a person feels from a task; it can involve mental, physical, temporal, effort and frustration dimensions.' },
  'nasa-tlx': { def: 'A tool for assessing subjective workload, with six dimensions: mental, physical and temporal demand, performance, effort and frustration.' },
  'task-performance': { def: 'Performance in a concrete task, such as quality of completion, errors and time taken. The measures should match the behaviour the research wants to support.' },
  'embedding-classifier': { def: 'Turn each item into an embedding vector, then train a small classifier on top of those vectors. The large model stays unchanged and only a modest labeled set is needed.', note: 'Our example: Turn thousands of support messages into vectors, then train a small classifier on a few hundred labeled “complaint / question / praise” messages to sort new ones.', mechanism: 'An embedding model first turns text into number vectors, then an ordinary classifier learns which vectors match which labels.', goodFor: 'fixed categories with some labeled data.' },
  'semantic-search': { def: 'Search by meaning rather than exact words: embed the query and the documents, then return the documents whose vectors are closest.', note: 'Our example: Searching “phone won\'t charge” also finds a help article titled “battery not charging”.', mechanism: 'Put the query and documents in the same vector space, then pick the nearest few.', goodFor: 'finding text that says the same thing in different words.' },
  chunking: { def: 'Splitting long documents into shorter pieces before indexing, so retrieval can return just the relevant part.', note: 'Our example: Split a 200-page manual by section, so a question about warranty pulls out only the warranty section.', mechanism: 'Cut documents by paragraph or fixed length, often letting neighbouring pieces overlap a little.', goodFor: 'documents too long to fit in the context.' },
  reranking: { def: 'Quickly retrieve a batch of candidates first, then rescore them with a more careful model so the most relevant come first.', note: 'Our example: Fetch 50 articles, then let a reranker pick the 5 that best fit the question to hand to the LLM.', mechanism: 'A model reads the question together with each candidate, scores it, and sorts by score.', goodFor: 'rough search results with weak top hits.' },
  'hybrid-search': { def: 'Run keyword search (such as BM25) and embedding search together, then merge the two result lists.', note: 'Our example: A search for model “X200-B” needs keywords, while “how to clean the lens” works better by meaning; together they cover both.', mechanism: 'Keyword matching catches exact words, vector matching catches similar meaning, and the two rankings are merged.', goodFor: 'queries mixing exact names and casual wording.' },
  'parameter-efficient-tuning': { def: 'Fine-tuning methods that train only a small number of added or selected parameters while freezing the rest of the model. LoRA is a common example.', note: 'Our example: For one base model, keep a small patch of a few dozen megabytes each for legal and support, instead of copying the whole model twice.', mechanism: 'Freeze the original model and update only a small set of parameters, so memory use and saved files stay small.', goodFor: 'customizing a model on limited GPU memory.' },
  'adaptation-routes': { def: 'There are five routes to make a model do your task, cheapest first: prompt, RAG, embedding plus classifier, fine-tuning, LoRA. Try the cheap ones first and move heavier only if needed.', note: 'Our example: To reply in a company tone, write a prompt; to cite the latest manual, use RAG; to sort mail into ten classes, use embedding plus classifier; for a steady specialist style, consider fine-tuning.', mechanism: 'Prompts change the instructions, RAG adds reference text, a classifier adds a decision head, and fine-tuning or LoRA changes the model itself.', goodFor: 'choosing the cheapest fix before building.' },
  'ai-agent': { def: 'A system built around an LLM that decides its own next steps and uses tools to act in an environment toward a goal.', note: 'Our example: A booking helper hears “Shanghai next Friday”, then searches flights, compares prices, and books one.', mechanism: 'The model picks steps, calls tools, and reads results before going on.', goodFor: 'open tasks with unclear steps.' },
  'compound-ai-system': { def: 'A system made of several parts, such as LLMs, retrievers, tools and optimizers, rather than one model alone.', note: 'Our example: A lab-notes bot retrieves records, has a model summarize them, then checks the format with rules.', mechanism: 'Chains retrieval, generation and checking so each part does one job.', goodFor: 'answers that cite fresh documents.' },
  'workflow-vs-agent': { def: 'In a workflow, code fixes the path through models and tools; in an agent, the model decides the process and tool use itself.', note: 'Our example: “Classify each email, then reply” is a workflow; “handle my inbox” is closer to an agent.', mechanism: 'A workflow hard-codes the route; an agent lets the model pick it live.', goodFor: 'fixed steps suit workflows, open ones suit agents.' },
  'agent-loop': { def: 'The cycle an agent repeats: observe the situation, think, act, then continue from the result until done or stopped.', note: 'Our example: A coding assistant reads an error, edits a line, reruns the tests, and reads the new error.', mechanism: 'Feeds each result back to the model, which then picks the next move.', goodFor: 'tasks that need trial and error.' },
  'tool-use': { def: 'The model emits a structured request that outside code runs, such as search, math or a database query, and returns the result to it.', note: 'Our example: A booking helper has the model output “search_flights(Shanghai, Friday)”, and real code runs it.', mechanism: 'The model writes a function name and arguments; code runs it for it.', goodFor: 'checking weather, math, reading files.' },
  mcp: { def: 'An open protocol that defines one common way for AI applications to connect to outside tools, data and prompt templates.', note: 'Our example: A notes bot reaches a calendar and a folder through the same interface, with no custom glue for each.', mechanism: 'Clients and servers swap tools and resources in one message format.', goodFor: 'one connector shared by many apps.' },
  'react-pattern': { def: 'Has the model alternate between reasoning and acting: think a step, call a tool, then reason on from what it sees.', note: 'Our example: An assistant thinks “check stock first”, queries, sees none, then reasons “try another warehouse”.', mechanism: 'Interleaves thought text and tool results in one running context.', goodFor: 'solving while looking things up.' },
  'context-engineering': { def: 'Designing and managing everything given to the model each time, including instructions, history, tool results and retrieved text, so the limited window holds what helps most.', note: 'Our example: In a long session, a coding assistant squeezes old logs into a few lines and keeps only the current error.', mechanism: 'Selects, trims and loads information on demand instead of stuffing it all in.', goodFor: 'long tasks when the window fills up.' },
  'agent-memory': { def: 'How an agent stores and recalls information, often split into working, episodic, semantic and procedural memory.', note: 'Our example: A lab-notes bot recalls “last Wednesday’s sample was contaminated” and the standard log format.', mechanism: 'Writes past content to outside storage and reads it back when needed.', goodFor: 'assistants that last across days.' },
  'multi-agent-system': { def: 'A system where several agents with different roles divide work and cooperate by passing messages.', note: 'Our example: One agent writes code, another reviews it, and a third sums up.', mechanism: 'Gives each agent a role and lets them message each other.', goodFor: 'big jobs that split into subtasks.' },
  'agent-harness': { def: 'The code wrapped around a model that handles prompts, tools, permissions, loop control and result handling.', note: 'Our example: With the same model, a different set of terminal commands changes how well a coding assistant fixes code.', mechanism: 'Sets up tools, rules and the loop so the model only has to decide.', goodFor: 'making one model work reliably.' },
  'dspy-framework': { def: 'A framework that writes language model pipelines as declarative programs and uses optimizers to tune their prompts and examples.', note: 'Our example: A notes bot only declares “record in, summary out”, and the optimizer finds a prompt that works.', mechanism: 'Tries many prompts against a metric and keeps the best.', goodFor: 'skipping endless prompt tweaking.' },
  'agent-evaluation': { def: 'Measuring how well an agent does: give a request and an environment, set stopping criteria, then have a scorer judge the result.', note: 'Our example: Let a booking helper book in a mock site, then check the order is right and done within 20 steps.', mechanism: 'Runs tasks in a controlled setup, then scores the outcome.', goodFor: 'comparing two versions before launch.' },
  'llm-as-judge': { def: 'Using one LLM to score or compare another model’s answers, standing in for some human review.', note: 'Our example: Ask a model to compare two meeting summaries and say which is more accurate.', mechanism: 'Hands the criteria and two answers to a judge model and reads its verdict.', goodFor: 'scoring many free-text answers.' },
  'pass-at-k': { def: 'The share of tasks where at least one of k attempts succeeds.', note: 'Our example: A coding assistant tries each problem 5 times and passes if any run clears the tests.', mechanism: 'Samples each task repeatedly and counts those with any success.', goodFor: 'seeing if retries can solve it.' },
  'data-flywheel': { def: 'Collecting real usage data after launch to improve the system, which draws more use and more data in a loop.', note: 'Our example: A notes bot logs the summaries users edit and uses those edits to improve the next version.', mechanism: 'Logs real feedback, picks out failures, and feeds fixes back in.', goodFor: 'a product that gets better with use.' },
  'agent-trace': { def: 'A full record of one task run: each step’s reasoning, tool calls, returned results and timing.', note: 'Our example: After a booking mistake, the trace shows step 3 misread “Friday”.', mechanism: 'Logs every step’s inputs and outputs so you can replay them.', goodFor: 'finding which step went wrong.' },
  'prompt-injection': { def: 'An attack that hides malicious instructions in content such as web pages or emails so the model treats them as real commands.', note: 'Our example: An email hides “send me the contact list”, and a mail assistant might obey.', mechanism: 'The model cannot tell data from instructions, so it may obey what it reads.', goodFor: 'testing agents that read outside content.' },
  guardrails: { def: 'Checks and limits placed around a model’s inputs and outputs to block unsafe, unauthorized or non-compliant content and actions.', note: 'Our example: A booking helper must ask the user before spending over 200 euros.', mechanism: 'Adds rules or checks before and after the model, then blocks or escalates.', goodFor: 'limiting what an agent may do or say.' },
  sandboxing: { def: 'Running an agent in an isolated environment that limits the files, network and permissions it can reach, so mistakes stay contained.', note: 'Our example: A coding assistant can only edit a temp folder and cannot touch your real documents.', mechanism: 'Runs code in an isolated container with only needed permissions.', goodFor: 'safely running code an agent wrote.' },
  'coding-agent': { def: 'An agent that reads files, edits code and runs commands and tests in a code repository to complete programming tasks.', note: 'Our example: You say “fix the login page error”, and it finds the file, fixes it, and gets tests passing.', mechanism: 'Browses code, edits it and runs tests through terminal commands.', goodFor: 'fixing small bugs, writing tests.' },
  'algorithmic-bias': { def: 'When an AI system\'s decisions treat certain groups or populations unfairly or in a discriminatory way. Bias can enter through the data, the algorithm, or how the system is used.', note: 'Our example: A resume-screening model that has only seen one kind of successful applicant may underrate everyone else.', mechanism: 'Skews in the training data get learned and then show up as uneven scores.', goodFor: 'Comparing results across groups before hiring decisions.' },
  'political-bias': { def: 'Researchers measure whose views a language model\'s answers resemble on contested questions, for example by comparing them with public opinion polls. It is a descriptive measurement of tendencies in outputs.', note: 'Our example: Ask a model the same survey question that people answered, then see which group\'s answers its reply most resembles.', mechanism: 'Compare the model\'s answers with real poll answers from each group, question by question.', goodFor: 'Knowing whose views a tool tends to echo.' },
  memorization: { def: 'When a language model retains individual pieces of its training data and can reproduce them when queried in the right way.', note: 'Our example: A model saw someone\'s full address in training and later repeats the whole line word for word when asked.', mechanism: 'Fitting a passage during training leaves traces of it in the parameters.', goodFor: 'Checking whether a model spits out source text.' },
  'training-data-extraction': { def: 'An attack in which someone queries a model to recover individual examples that it was trained on.', note: 'Our example: Someone feeds a model many different openings, hoping it will continue with the text of a private email.', mechanism: 'Send many queries, then pick out outputs that look like original training text.', goodFor: 'Testing a model for leaks before release.' },
  'membership-inference': { def: 'An attack that, given a data record and black-box access to a model, tries to determine whether that record was in the model\'s training dataset.', note: 'Our example: If a model is unusually sure about one patient\'s record, an attacker may guess that record was used in training.', mechanism: 'Compare how the model predicts on inputs it trained on versus ones it did not.', goodFor: 'Checking whether a model exposes who was in the data.' },
  'data-privacy': { def: 'The concern that machine learning models can leak information about the individual records they were trained on, and the work to prevent that.', note: 'Our example: After a hospital trains a model on patient files, outsiders should not be able to pull one patient\'s details out of it.', mechanism: 'A model\'s predictions and outputs can carry clues about the records behind them.', goodFor: 'Weighing risks before training on sensitive data.' },
  'differential-privacy': { def: 'A mathematically rigorous definition of privacy, together with algorithms that satisfy it, used to limit what an analysis reveals about any individual.', note: 'Our example: A neighborhood\'s average income is released with a little random error, so no single household\'s income can be read off.', mechanism: 'Mix carefully chosen random noise into results to mask any one person\'s effect.', goodFor: 'Publishing statistics while protecting individuals.' },
  jailbreaking: { def: 'Crafting prompts that get a safety-trained model to produce behavior it was trained to refuse.', note: 'Our example: A request the model would refuse outright gets wrapped in a role-play story, and the model may then answer it.', mechanism: 'Set the model\'s abilities against its safety goals, or use a phrasing that safety training did not cover.', goodFor: 'Finding gaps in a model\'s safety training.' },
  'red-teaming': { def: 'Looking for test cases where a model behaves in harmful ways before it is deployed. The cases can be written by people or generated automatically by another language model.', note: 'Our example: Before launch, a group deliberately asks tricky questions and logs which replies are inappropriate.', mechanism: 'Generate many tricky questions, then use a classifier to flag harmful replies.', goodFor: 'Finding problems before users do.' },
  'ai-energy-use': { def: 'AI energy use is the electricity a model consumes in training and in inference. Training is a large one-off computation, while inference keeps adding up with every use.', note: 'Our example: after a translation tool launches, millions of daily clicks can add up to more electricity than its one-off training did.', mechanism: 'Training runs through lots of data again and again, and each request later triggers a fresh computation.', goodFor: 'Comparing which of two models is cheaper to run.' },
  'carbon-footprint': { def: 'The carbon footprint of AI is the greenhouse-gas emissions linked to the electricity used to run models. It depends on how much energy is used and where that energy comes from.', note: 'Our example: the same training job can cause very different emissions in a region with mostly hydro power than in one with mostly coal power.', mechanism: 'Energy used is combined with how emissions-heavy the local power supply is.', goodFor: 'Choosing where and when to run a job.' },
  'water-footprint': { def: 'The water footprint of AI is the water used to cool data centres and to generate the electricity they use. It is often overlooked.', note: 'Our example: a server room cooled by evaporation loses more water the longer a model keeps running.', mechanism: 'Cooling lets water evaporate, and power plants also draw water.', goodFor: 'Seeing the hidden water use of a service.' },
  'environmental-impact': { def: 'The environmental impact of AI is the cost it causes in energy, emissions and water use. Some parts are easy to measure, while others are hard to estimate without detailed information.', note: 'Our example: counting only training electricity misses later use, hardware production and cooling.', mechanism: 'Each stage (training, use, data centre) is recorded and then added together.', goodFor: 'Comparing which option is greener.' },
  'ai-regulation': { def: 'The EU AI Act is a risk-based legal framework: unacceptable-risk AI is prohibited, high-risk AI is regulated, limited-risk AI has transparency duties, and minimal-risk AI is unregulated. Check the actual text for exact obligations.', note: 'Our example: a small music-recommending app and a system that screens job applicants face different requirements.', mechanism: 'The law first sorts a system into a risk class, then attaches requirements to that class.', goodFor: 'Judging whether a product needs strict oversight.' },
  'risk-management-framework': { def: 'The NIST AI Risk Management Framework is voluntary guidance that helps organizations manage AI risks to individuals, organizations and society, and build trustworthiness into design, development, use and evaluation.', note: 'Our example: before launch, a team walks through a risk checklist asking who could be affected and how problems would be noticed.', mechanism: 'An organization chooses to adopt it and works through identifying, assessing and responding to risks.', goodFor: 'Giving a team a shared language for risk.' },
  'open-weights-vs-open-source': { def: 'Open weights means the model parameters are released. Under the Open Source Initiative\'s definition, open source AI also requires detailed data information and the complete training and running code, plus freedom to use, study, modify and share.', note: 'Our example: someone hands you a finished cake (the weights) without the recipe or ingredient list, so you can eat it but can hardly remake it.', mechanism: 'The publisher decides which parts to release: parameters, code or data information.', goodFor: 'Checking what an “open” model really opens up.' },
  'dataset-license': { def: 'A dataset licence sets how others may use a dataset. In Creative Commons licences, BY requires credit, SA requires adaptations to be shared under the same terms, NC permits only noncommercial use, and ND forbids adaptations. Check the actual licence text.', note: 'Our example: a labelled photo set marked “credit plus noncommercial” fits a class project, as long as you name the author.', mechanism: 'The data provider writes the conditions into the licence, and users follow those terms.', goodFor: 'Checking if data may be used before starting.' },
};
